package cn.iocoder.yudao.module.zsjos.service.positioning;
import cn.iocoder.yudao.module.zsjos.dal.dataobject.positioning.PositioningCardDO; import cn.iocoder.yudao.module.zsjos.dal.mysql.personnel.PartnerStudentLinkMapper; import cn.iocoder.yudao.module.zsjos.service.personnel.PartnerAccountService; import cn.iocoder.yudao.module.zsjos.controller.app.positioning.vo.PositioningConfirmationRespVO; import jakarta.annotation.Resource; import org.springframework.stereotype.Service; import static cn.iocoder.yudao.framework.common.exception.util.ServiceExceptionUtil.exception; import static cn.iocoder.yudao.module.zsjos.enums.ZsjosErrorCodeConstants.POSITIONING_CARD_PERMISSION_DENIED;
@Service public class PositioningConfirmationService { @Resource private PositioningCardService cardService; @Resource private PartnerAccountService accountService; @Resource private PartnerStudentLinkMapper linkMapper;
 public PositioningConfirmationRespVO detail(Long cardId,Long accountId){var card=cardService.require(cardId);var ctx=accountService.requireContext(accountId);if(linkMapper.selectActiveByPartner(ctx.partnerId())==null)return PositioningConfirmationRespVO.pending();require(cardId,accountId);return PositioningConfirmationRespVO.ready(card);}
 public void confirm(Long id,Integer version,Long accountId){var card=require(id,accountId);cardService.studentConfirm(card.getId(),version);}
 public void reject(Long id,Integer version,Long accountId){var card=require(id,accountId);cardService.studentReject(card.getId(),version);}
 private PositioningCardDO require(Long id,Long accountId){var card=cardService.require(id);var ctx=accountService.requireContext(accountId);var link=linkMapper.selectActiveByPartner(ctx.partnerId());if(link==null||card.getStudentPersonId()==null||!card.getStudentPersonId().equals(link.getStudentPersonId()))throw exception(POSITIONING_CARD_PERMISSION_DENIED);return card;}
}
